import{_ as d,o as t,c as o,a3 as c}from"./chunks/framework.qCVWde4n.js";const m=JSON.parse('{"title":"使用手机自身的功能","description":"","frontmatter":{},"headers":[],"relativePath":"zh/device.md","filePath":"zh/device.md"}'),a={name:"zh/device.md"};function n(s,e,i,r,l,p){return t(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="手机自己的能力" tabindex="-1">使用手机自身的功能 <a class="header-anchor" href="#手机自己的能力" aria-label="Permalink to &quot;使用手机自身的功能 {#手机自己的能力}&quot;">​</a></h1><blockquote><p><strong>旧版 Python 实现的设计记录</strong>。当前 Android App 使用 OpenMinis 提供的设备工具，并通过 Reach 和 hub（设备互联）访问电脑，见 <a href="./android">android.md</a>、<a href="./hub">hub.md</a>。下文提到的 connect 构建已不再提供。</p></blockquote><p>在手机上运行时，nanoMuse 可以使用剪贴板、日历、联系人、位置、时钟 App 的闹钟和计时器、通知栏，以及通过系统选择器选中的照片。本文说明这些功能如何接入、每个工具能做什么、何时需要用户授权，以及它们的访问边界。</p><p>设计原则是：模型通过工具调用手机功能，授权则由 Android 自己的对话框完成。nanoMuse 不能给自己授权。每项权限都由系统询问用户，照片必须由用户在系统选择器中选择，闹钟交给用户已有的时钟 App 设置。Python 智能体无需为了手机而更改实现，Kotlin 程序负责提供这些工具。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> nanomuse serve (Python, in PRoot)                 the app (Kotlin)</span></span>
<span class="line"><span> ┌──────────────────────────────┐   HTTP, 127.0.0.1    ┌───────────────────────────────┐</span></span>
<span class="line"><span> │ MCP client  ── device__* ────┼──────────────────────►│ McpEndpoint  (Streamable HTTP) │</span></span>
<span class="line"><span> │ Sentinel: per-tool defaults  │   Bearer / ?token=    │  DeviceTools: 13 tools         │</span></span>
<span class="line"><span> │ nanomuse-device (CLI bridge) │◄──────────────────────┤  Ask: Android&#39;s dialogs        │</span></span>
<span class="line"><span> └──────────────────────────────┘   SSE + heartbeats    │  DeviceAskActivity (invisible) │</span></span>
<span class="line"><span>                                                        └───────────────────────────────┘</span></span></code></pre></div><h2 id="how-the-tools-reach-the-model" tabindex="-1">模型如何获得这些工具 <a class="header-anchor" href="#how-the-tools-reach-the-model" aria-label="Permalink to &quot;模型如何获得这些工具 {#how-the-tools-reach-the-model}&quot;">​</a></h2><p>App 会在 <code>127.0.0.1</code> 上启动 MCP 服务器。MCP 是让智能体发现并调用工具的协议。服务器使用随机端口和随机令牌，分别通过 <code>NANOMUSE_HOST_URL</code> 和 <code>NANOMUSE_HOST_TOKEN</code> 交给运行时（执行智能体任务的程序）。<code>nanomuse serve</code> 读取后，将服务器注册为 <code>device</code>，无需手动配置或安装。工具与其他 MCP 工具一样使用，名称为 <code>device__&lt;tool&gt;</code>，例如 <code>device__calendar_list</code>、<code>device__clipboard_read</code>。系统提示词会加入「这台手机」一节，列出工具，并说明基本约束：首次使用某项功能时 Android 会请求用户授权；只有 App 位于前台时才能读取剪贴板。</p><p>接口使用 <a href="https://modelcontextprotocol.io/specification/2025-03-26/basic/transports" target="_blank" rel="noreferrer">Streamable HTTP</a> 传输，通过 <code>POST /mcp</code> 接收 JSON-RPC 格式的请求。<code>tools/call</code> 用 SSE（服务器持续推送事件的连接）返回结果，并每 8 s 发送一行 <code>: keep-alive</code> 心跳，因为等待用户操作对话框可能需要几分钟。<code>GET /mcp</code> 返回 <code>405</code>。令牌可放在 <code>Bearer</code> 请求头或 <code>?token=</code> 参数中。服务器在 <code>initialize</code> 时发出 <code>Mcp-Session-Id</code> 请求头，并原样返回客户端的 <code>protocolVersion</code>。服务仅提供 <code>/mcp</code> 路径，只监听本机回环接口；缺少正确令牌的请求会被拒绝，令牌使用恒定时间比较。</p><p>智能体在沙箱内运行的脚本，也能通过命令行桥接访问这些工具，见 <a href="./local-runtime#the-python-side-on-a-phone">local-runtime.md</a>。例如：<code>nanomuse-device clipboard read</code>、<code>nanomuse-device calendar list from=2026-09-24</code>、<code>nanomuse-device alarm set hour=7 minute=30 message=Train</code>、<code>nanomuse-device notify title=Done body=Booked</code>、<code>nanomuse-device location</code>、<code>nanomuse-device photo pick</code>。<code>nanomuse-device list</code> 可以列出手机支持的功能。这些调用与模型直接调用一样，都经过哨兵（Sentinel）检查。</p><h2 id="the-tools" tabindex="-1">工具列表 <a class="header-anchor" href="#the-tools" aria-label="Permalink to &quot;工具列表 {#the-tools}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>功能</th><th>参数</th><th>Android 权限</th><th>风险</th><th><code>ask</code> 模式下需要审批？</th></tr></thead><tbody><tr><td><code>clipboard_read</code></td><td>读取剪贴板文字</td><td>—</td><td>无，但 Android 10+ 要求 <strong>App 位于前台</strong></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>clipboard_write</code></td><td>将文字写入剪贴板</td><td><code>text</code></td><td>无</td><td>safe</td><td>否</td></tr><tr><td><code>notify</code></td><td>发送通知，点击后打开聊天</td><td><code>title</code>、<code>body</code>、<code>thread</code></td><td><code>POST_NOTIFICATIONS</code>（13+）</td><td>safe</td><td>否</td></tr><tr><td><code>calendars</code></td><td>列出手机上的日历</td><td>—</td><td><code>READ_CALENDAR</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>calendar_list</code></td><td>查询指定时间段的日程，可按关键词筛选</td><td><code>from</code>、<code>to</code>、<code>query</code>、<code>calendar_id</code>、<code>limit</code></td><td><code>READ_CALENDAR</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>calendar_create</code></td><td>新建日程，全天日程使用日期</td><td><code>title</code>、<code>start</code>、<code>end</code>、<code>all_day</code>、<code>location</code>、<code>description</code>、<code>calendar_id</code>、<code>reminder_minutes</code></td><td><code>WRITE_CALENDAR</code></td><td>moderate</td><td>否</td></tr><tr><td><code>calendar_update</code></td><td>修改传入的日程字段</td><td><code>id</code>、<code>title</code>、<code>start</code>、<code>end</code>、<code>all_day</code>、<code>location</code>、<code>description</code></td><td><code>WRITE_CALENDAR</code></td><td>moderate</td><td>否</td></tr><tr><td><code>calendar_delete</code></td><td>删除日程</td><td><code>id</code></td><td><code>WRITE_CALENDAR</code></td><td><strong>sensitive</strong></td><td><strong>是</strong></td></tr><tr><td><code>contacts_search</code></td><td>按姓名、号码或邮箱查找联系人，只读</td><td><code>query</code>、<code>limit</code></td><td><code>READ_CONTACTS</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>location</code></td><td>获取坐标和精度，能解析时也返回地址</td><td><code>accuracy</code>（<code>fine</code>/<code>coarse</code>）、<code>max_age_seconds</code></td><td><code>ACCESS_FINE_LOCATION</code> / <code>ACCESS_COARSE_LOCATION</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>alarm_set</code></td><td>在时钟 App 中设置闹钟</td><td><code>hour</code>、<code>minute</code>、<code>message</code>、<code>days</code>、<code>vibrate</code></td><td><code>SET_ALARM</code>（安装时授予）</td><td>moderate</td><td>否</td></tr><tr><td><code>timer_set</code></td><td>在时钟 App 中设置倒计时</td><td><code>seconds</code> 或 <code>minutes</code>、<code>message</code></td><td><code>SET_ALARM</code></td><td>moderate</td><td>否</td></tr><tr><td><code>photo_pick</code></td><td>由用户在系统选择器中挑选照片，并复制到工作区</td><td><code>max</code>（≤ 10）、<code>why</code></td><td>无，Photo Picker 不需要权限</td><td>safe，隐私</td><td>否</td></tr></tbody></table><p>表中的风险等级和隐私标记来自 <code>nanomuse/runtime.py</code> 的 <code>DEVICE_TOOLS</code>，是哨兵为这些工具设置的默认值。<code>safe</code>、<code>moderate</code>、<code>sensitive</code> 分别表示安全、中等和敏感风险。默认值通过 MCP 服务器条目的 <code>tools</code> 映射逐项应用，见 <a href="./configuration#mcp-servers">configuration.md</a>。「需要审批」指哨兵是否询问你允许此次操作，对应 <a href="./sentinel">sentinel.md</a> 中的 <code>ask</code> 模式；在 <code>strict</code> 模式下，moderate 工具也都需要审批。标为隐私的工具会将当前对话标记为已污染，即后续可能包含私密信息。例如调用 <code>contacts_search</code> 或 <code>location</code> 后，向未知主机发送数据的操作都需要你确认。时间采用手机当地时间，格式为 <code>YYYY-MM-DD HH:MM</code>，全天日程只用日期；全天日程的结束时间显示为最后一天。<code>location</code> 的地址由手机平台的地理编码服务解析，没有该服务时只返回坐标。</p><p>Kotlin 的 <code>DeviceTools.kt</code> 与 Python 的 <code>DEVICE_TOOLS</code> 必须保持一致。<code>tests/test_bridge.py</code> 会检查工具名称和默认规则。</p><h2 id="what-the-user-sees" tabindex="-1">用户看到的授权流程 <a class="header-anchor" href="#what-the-user-sees" aria-label="Permalink to &quot;用户看到的授权流程 {#what-the-user-sees}&quot;">​</a></h2><p>工具需要用户确认时，都通过 Android 对话框完成。App 使用不可见的 activity（Android 界面组件）<code>DeviceAskActivity</code> 打开对话框，让智能体无论在哪里执行都能请求授权。Android 10+ 不允许后台 App 直接启动 activity，因此分两种情况：</p><ul><li><strong>App 位于前台</strong>：对话框立即显示在 App 上方。</li><li><strong>App 位于后台</strong>：先发送通知，例如「nanoMuse 需要一项权限」「nanoMuse 想读取剪贴板」或「nanoMuse 想要一张照片」，并用一行文字说明原因。点击通知后才显示对话框。工具会等待结果：权限最多等 2 分钟，剪贴板 1.5 分钟，照片 4 分钟。无论结果如何，模型都会收到说明。</li></ul><p>模型收到三种结果之一：用户已允许，工具继续执行；用户未允许，当前不要再次询问，之后可在 Android 设置中授权；无人回应，请用户打开 nanoMuse 后重试。这些说明可以直接转述给用户。</p><p>以下行为由 Android 平台规则决定：</p><ul><li><strong>剪贴板</strong>。从 Android 10 起，只有获得焦点的 App 能读取剪贴板。因此后台发起 <code>clipboard_read</code> 时先发通知，用户点击通知的那一刻才读取。写入不受前台限制。</li><li><strong>闹钟和计时器</strong>。工具使用标准 <code>AlarmClock</code> intent（交给其他 App 处理的系统请求）调用时钟 App，跳过它的设置界面，生成的闹钟与手动设置相同。App 位于前台，或具有「显示在其他应用上层」权限时，会立即完成交接。后台时 Android 禁止直接启动其他 App，因此先发通知，用户点击后才设置闹钟。工具使用手机已有的时钟 App；如果没有，会明确告知。</li><li><strong>照片</strong>。仅通过 <a href="https://developer.android.com/training/data-storage/shared/photopicker" target="_blank" rel="noreferrer">Photo Picker</a> 访问。用户选中哪些照片，App 就只获得哪些，将副本放入 <code>workspace/attachments/&lt;date&gt;/</code> 并返回路径。相册其他内容不可读取，也不会申请 <code>READ_MEDIA_IMAGES</code>。系统选择器界面也会说明这个范围。</li><li><strong>位置</strong>。使用平台 <code>LocationManager</code>，不依赖 Play 服务。上次定位足够新时直接使用，时效由 <code>max_age_seconds</code> 控制，默认 2 分钟；否则重新定位，最多等待 25 s。<code>coarse</code> 只申请大致位置权限。</li><li><strong>联系人与日历</strong>。联系人只能读取；日历通过系统内容提供器读写。删除日程是其中始终需要审批的操作。</li><li><strong>通知</strong>。<code>notify</code> 通过普通通知渠道发送，点击后打开相应对话线程。不提供读取通知栏功能，因为它需要「通知使用权」，Android 将其视为覆盖整个设备的特殊权限。如果以后实现这项功能（P2），会提供单独开关，默认关闭，并在哨兵规则表中单独列出。</li></ul><h2 id="the-workspace-in-the-files-app" tabindex="-1">在「文件」App 中访问工作区 <a class="header-anchor" href="#the-workspace-in-the-files-app" aria-label="Permalink to &quot;在「文件」App 中访问工作区 {#the-workspace-in-the-files-app}&quot;">​</a></h2><p>local 构建会注册 <code>DocumentsProvider</code>，通过 Android 存储访问框架把智能体工作区显示为一个以智能体命名的根目录。你可以在系统「文件」App，以及手机上的打开或保存对话框中访问它。智能体生成的是普通文件，放入该目录的文件也会进入工作区。隐藏条目和浏览器配置目录不显示。connect 构建不在手机上保存工作区，因此不会显示该根目录。</p><h2 id="sharing-into-nanomuse" tabindex="-1">分享到 nanoMuse <a class="header-anchor" href="#sharing-into-nanomuse" aria-label="Permalink to &quot;分享到 nanoMuse {#sharing-into-nanomuse}&quot;">​</a></h2><p>系统分享面板支持将文字、链接和文件分享给 nanoMuse。每次分享都会创建新对话：文件上传到工作区的 <code>attachments/&lt;date&gt;/…</code>，对话按主题或第一个文件命名；打开聊天后，分享文字先放在输入框中作为草稿，文件显示为附件标签，等待你说明如何处理。你发送指令前，不会向模型发送任何内容。两个构建都支持该流程，其中 connect 构建将文件上传到电脑。</p><h2 id="connect-mode" tabindex="-1">connect 模式 <a class="header-anchor" href="#connect-mode" aria-label="Permalink to &quot;connect 模式 {#connect-mode}&quot;">​</a></h2><p>connect 构建将手机作为电脑上 <code>nanomuse serve</code> 的远程界面。它虽然包含同样的 Kotlin 工具，但电脑服务器无法访问手机的 <code>127.0.0.1</code>，需要通过手机 WebSocket（保持双向通信的网络连接）转发请求。旧版计划将其列为 P1，见 <a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/launch-checklist.md" target="_blank" rel="noreferrer">launch-checklist.md</a>。在该功能实现前，设备工具只能由手机本地运行时使用。</p><h2 id="testing-without-a-phone" tabindex="-1">没有手机时如何测试 <a class="header-anchor" href="#testing-without-a-phone" aria-label="Permalink to &quot;没有手机时如何测试 {#testing-without-a-phone}&quot;">​</a></h2><p>x86_64 模拟器无法运行 arm64 PRoot 运行时，但可以直接测试 Kotlin 工具服务。connect 的 debug 构建会自行启动 MCP 服务器，并打印日志 <code>device MCP (debug): http://127.0.0.1:&lt;port&gt;/mcp token=&lt;token&gt;</code>。随后运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:9410</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">por</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># any MCP client, e.g. the reference Python one:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   streamable_http_client(&quot;http://127.0.0.1:9410/mcp?token=&lt;token&gt;&quot;)</span></span></code></pre></div><p><code>adb shell pm revoke &lt;app id&gt; android.permission.READ_CALENDAR</code> 可以撤销日历权限，让系统再次显示授权对话框；<code>adb shell input keyevent KEYCODE_HOME</code> 可以让 App 退到后台，测试通知流程；<code>adb emu geo fix &lt;lon&gt; &lt;lat&gt;</code> 可以为 <code>location</code> 提供模拟坐标。<code>McpEndpointTest</code> 在 JVM 上测试传输协议，包括 initialize、<code>tools/list</code>、带心跳的 SSE 调用、将工具失败表示为 <code>isError</code>，以及错误令牌和请求方法。</p><h2 id="not-in-this-release" tabindex="-1">这个版本不提供的功能 <a class="header-anchor" href="#not-in-this-release" aria-label="Permalink to &quot;这个版本不提供的功能 {#not-in-this-release}&quot;">​</a></h2><p>不提供读取通知、修改联系人、访问整个相册、读取短信和通话记录，也不提供 connect 模式的设备请求转发。以后加入这些功能时，每项都会有独立开关，并默认关闭。</p>`,31)])])}const u=d(a,[["render",n]]);export{m as __pageData,u as default};
